import{z as B,x as i,o as E,c as D,q as o,j as t,D as e,d as r,s,S as n,b as p}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"KL 散度与交叉熵","description":"","frontmatter":{"title":"KL 散度与交叉熵","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/kl-cross-entropy.md","filePath":"cs/kl-cross-entropy.md","lastUpdated":1791063341000}'),q={name:"cs/kl-cross-entropy.md"};function d(A,a,C,m,h,u){const l=i("Mermaid");return E(),D("div",null,[a[2]||(a[2]=o('<h1 id="kl-散度与交叉熵" tabindex="-1">KL 散度与交叉熵 <a class="header-anchor" href="#kl-散度与交叉熵" aria-label="Permalink to &quot;KL 散度与交叉熵&quot;">​</a></h1><div class="epigraph"><p>$D(p\\|q)=\\sum p\\log\\frac{p}{q}$ 是用 $q$ 给真正来自 $p$ 的符号编码时，多付的平均比特；交叉熵 $H(p,q)=H(p)+D(p\\|q)$。</p><footer>—— 据 Kullback and Leibler, 1951；Cover and Thomas 整理</footer></div><p>上一课<a href="/cs/rate-distortion">率失真</a> 的目标里出现 \\(I(X;\\hat X)=D(p(x,\\hat x)\\|p(x)p(\\hat x))\\)。主干<a href="/cs/entropy-bits">熵</a> 有 \\(H\\)，互信息课有 \\(I\\)。缺口是把<strong>相对熵</strong>写成编码多付的比特，并接上交叉熵——后课最大熵、以及别处训练损失都用这个差，本栏只钉信息论。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>\\(D(p\\|q)\\ge 0\\)，等号当 \\(p=q\\)（Gibbs）。不对称：\\(D(p\\|q)\\ne D(q\\|p)\\)。不是度量。编码：若按 \\(q\\) 做理想码长 \\(-\\log q\\)，真实期望是 \\(-\\sum p\\log q=H(p,q)\\)，比 \\(H(p)\\) 多 \\(D(p\\|q)\\)。模型错了，压缩变差，下界仍是真熵。</p><p>链式：\\(D(p(x,y)\\|q(x,y))=D(p(x)\\|q(x))+D(p(y|x)\\|q(y|x))\\)。互信息 \\(I(X;Y)=D(p(x,y)\\|p(x)p(y))\\)。</p><h3 id="不是「距离」也不是准确率" tabindex="-1">不是「距离」也不是准确率 <a class="header-anchor" href="#不是「距离」也不是准确率" aria-label="Permalink to &quot;不是「距离」也不是准确率&quot;">​</a></h3><p>KL 可无穷（\\(q\\) 在 \\(p\\) 的支撑上为零）。交叉熵最小 \\(\\ne\\) 分类正确率最大，除非把 \\(q\\) 解释成 softmax 一类模型——那是用法，本课定义不依赖标签。</p><p><span class="marginnote">Kullback–Leibler 1951。Cover–Thomas 第 2 章。Sanov、大偏差把 \\(D\\) 当指数速率，点名。本课不把注意力或 token 损失写进主线。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>用二元 \\(p\\ne q\\) 算一个数，解释多付的比特。强调顺序：\\(p\\) 真、\\(q\\) 码本。对照 Hamming：几何距离不管 \\(p\\)；KL 不管几何，只管测度。</p>',11)),(E(),t(n,null,{default:e(()=>[s(l,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22%E7%9C%9F%20p%22%5D%20--%3E%20H%5B%22H(p)%20%E7%90%86%E6%83%B3%E7%A0%81%E9%95%BF%22%5D%0A%20%20Q%5B%22%E6%A8%A1%E5%9E%8B%20q%22%5D%20--%3E%20CE%5B%22%E4%BA%A4%E5%8F%89%E7%86%B5%20H(p%2Cq)%22%5D%0A%20%20H%20--%3E%20KL%5B%22%E5%B7%AE%20%3D%20D(p%7C%7Cq)%22%5D%0A%20%20CE%20--%3E%20KL%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=p("h2",{id:"机制",tabindex:"-1"},[r("机制 "),p("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=p("p",null,"有了 \\(D\\)，最大熵「在约束下让 \\(p\\) 尽量无偏」可写成最小化相对均匀的 \\(D\\)，下一课。信道、率失真的优化都是在凸集上动 \\(D\\) 或 \\(I\\)。本课只把尺子交到手上。",-1)),a[5]||(a[5]=p("p",null,"数据处理：Markov 链上 \\(D\\) 不增，点名。",-1)),a[6]||(a[6]=p("p",null,"Pinsker：\\(\\|p-q\\|_1^2 \\le 2D(p\\|q)\\)，把 KL 换成全变差。数据处理：Markov \\(X\\to Y\\to Z\\) 则 \\(D(p_Z\\|q_Z)\\le D(p_Y\\|q_Y)\\)。交叉熵作为训练损失时，\\(p\\) 是经验分布、\\(q\\) 是模型——那是用法；本课定义不依赖样本。反向 KL 与正向 KL 的零强迫不同，变分推断点名。",-1)),a[7]||(a[7]=p("p",null,"不对称不只是个代数性质：对同一个双峰真分布 \\(p\\)，最小化两个方向的 KL 会给出形状完全不同的 \\(q\\)。",-1)),(E(),t(n,null,{default:e(()=>[s(l,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22%E7%9C%9F%E5%88%86%E5%B8%83%20p%EF%BC%9A%E5%8F%8C%E5%B3%B0%22%5D%20--%3E%20WHICH%7B%22%E6%8B%9F%E5%90%88%E6%96%B9%E5%90%91%EF%BC%9F%22%7D%0A%20%20WHICH%20--%3E%7C%22%E6%9C%80%E5%B0%8F%E5%8C%96%20D(p%E2%88%A5q)%EF%BC%9A%E6%AD%A3%E5%90%91%22%7C%20FWD%5B%22p%20%E6%9C%89%E8%B4%A8%E9%87%8F%E5%A4%84%20q%20%E4%B8%8D%E8%83%BD%E4%B8%BA%E9%9B%B6%3Cbr%3Eq%20%E9%93%BA%E5%BC%80%E7%9B%96%E4%BD%8F%E4%B8%A4%E5%B3%B0%22%5D%0A%20%20WHICH%20--%3E%7C%22%E6%9C%80%E5%B0%8F%E5%8C%96%20D(q%E2%88%A5p)%EF%BC%9A%E5%8F%8D%E5%90%91%22%7C%20REV%5B%22q%20%E5%9C%A8%20p%20%E4%B8%BA%E9%9B%B6%E5%A4%84%E6%94%BE%E8%B4%A8%E9%87%8F%E5%88%99%E6%97%A0%E7%A9%B7%E6%83%A9%E7%BD%9A%3Cbr%3Eq%20%E6%94%B6%E7%BC%A9%E9%94%81%E6%AD%BB%E5%8D%95%E5%B3%B0%22%5D%0A%20%20FWD%20--%3E%20C1%5B%22%E8%A6%86%E7%9B%96%E5%BC%8F%EF%BC%9A%E4%B8%8D%E6%BC%8F%E4%BD%86%E5%8F%AF%E8%83%BD%E6%91%8A%E5%B9%B3%22%5D%0A%20%20REV%20--%3E%20C2%5B%22%E8%BF%BD%E5%B3%B0%E5%BC%8F%EF%BC%9A%E9%9B%86%E4%B8%AD%E4%BD%86%E4%BC%9A%E6%BC%8F%E5%B3%B0%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=o('<p><span class="marginnote">数字实例：取二元 \\(p=(0.5,0.5)\\)、\\(q=(0.9,0.1)\\)，按 2 为底算：\\(D(p\\|q)=0.5\\log_2(0.5/0.9)+0.5\\log_2(0.5/0.1)\\approx 0.74\\) 比特；反着算 \\(D(q\\|p)\\approx 0.53\\) 比特。同两个分布、两个不同的数——「不对称」不是抽象警告，代入就看得见。</span></p><p><span class="marginnote">直觉类比：交叉熵是你寄 100 封信实际付的邮资，\\(H(p)\\) 是按真实频率设计价目表后的最优邮资，\\(D(p\\|q)\\) 就是「价目表选错」每天白花的冤枉钱——模型 \\(q\\) 再接近一点，多付的就少一点，但永远不会低于真熵这根下界。</span></p><p><span class="marginnote">常见误区：初学者容易把 KL 当距离，随手交换 \\(p\\|q\\) 的顺序，或以为 \\(D(a,b)+D(b,c)\\ge D(a,c)\\)。KL 不是度量：不对称、不满足三角不等式，且 \\(q\\) 在 \\(p\\) 有质量处取零时直接无穷——它是一把单向的尺，方向（谁是真、谁是码本）必须钉死。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 \\(f\\)-散度族全文，不证 Pinsker。不把反向 KL 与正向 KL 的变分推断写完。后课默认：\\(D(p\\|q)\\) 是额外码长；交叉熵 \\(=H+D\\)。下一课最大熵原理。</p><p>\\(p\\) 是真、\\(q\\) 是码本或模型，顺序不能翻。\\(D\\) 不是度量，可以无穷。互信息是到独立乘积的 KL，率失真与信道都在这把尺子上优化。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>\\(D(p\\|q)\\) 非负、不对称；编码解释为多付比特。</li><li>交叉熵 \\(=H(p)+D(p\\|q)\\)。</li><li>\\(I\\) 是到乘积分布的 KL。</li><li>出处：Kullback and Leibler, 1951；Cover and Thomas。</li></ul>',8))])}const f=B(q,[["render",d]]);export{c as __pageData,f as default};
